        const hueSpread = hueMaxC>=0 ? (hueMaxC-hueMinC) : 0;
        const varScore = Math.min(1, lVar/100) * 0.65 + Math.min(1, hueSpread/60) * 0.35;
        _flat = 1 - varScore;
